package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class GrantTypesJsonVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property grant types json of trusted client ")
  void test_grant_types_json_v_o_builder() {
    Assertions.assertFalse(GrantTypesJsonVO.nullValue().getGrantTypesJson().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(GrantTypesJsonVO.tryFrom(null).getGrantTypesJson().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", GrantTypesJsonVO.from("one").getGrantTypesJson().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> GrantTypesJsonVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", GrantTypesJsonVO.from("one").toString());
  }
}
